import {readDrafts,saveDraft,draftMarkdown} from './creation-model.mjs';
export const planningPages=new Set(['creation','account-info','warehouse']);
export function createPlanningViews({api,h,heading,notify}){
 const $=s=>document.querySelector(s);
 const blank=(title,desc)=>`<div class="empty"><h3>${h(title)}</h3><p>${h(desc)}</p></div>`;
 function accountIndex(){ $('#main').innerHTML=heading('账户资料','资料只维护一次，从这里进入对应的经营档案。')+`<div class="index-grid"><a class="index-card" href="#shops"><span>01</span><h2>店铺经营资料</h2><p>店铺名称、启停与业务归属，由产品和财务共同引用。</p><b>查看店铺资料 →</b></a><a class="index-card" href="#accounts"><span>02</span><h2>业务运营账号</h2><p>运营账号负责人、使用状态与主页资料，和系统登录用户分开。</p><b>查看运营账号 →</b></a><a class="index-card" href="#profile"><span>03</span><h2>本人资料</h2><p>当前登录身份及关联的成员基础档案。</p><b>查看本人资料 →</b></a></div><p class="muted">这里先作为资料索引，不维护第二份店铺或运营账号信息。</p>`;}
 async function inventory(signal){const rows=await api.products(signal);if(signal.aborted)return;$('#main').innerHTML=heading('仓库管理','产品和包材库存使用真实出入库事实，样品领还单独管理。')+`<div class="planning-rule">产品/包材库存和出入库接口尚未接入。以下为可关联的产品档案，数量显示“未接入”，不表示库存为零。</div><section class="work-panel module-panel" style="margin-top:24px"><div class="panel-head"><h2>产品库存</h2></div><table class="record-table"><thead><tr><th>产品档案</th><th>所属店铺</th><th>可用库存</th><th>出入库流水</th></tr></thead><tbody>${rows.map(p=>`<tr><td><button class="table-title" data-product-detail="${h(p.id)}">${h(p.name)}</button></td><td>${h(p.storeName||'未关联')}</td><td>未接入</td><td>未接入</td></tr>`).join('')}</tbody></table>${rows.length?'':blank('暂无可关联的产品档案','不会自动生成库存数据。')}</section><section class="work-panel planning-panel" style="margin-top:24px"><h2>包材库存</h2><p class="muted">包材档案、计量单位、入库和领用流水需要新增对应底层能力。</p><a class="text-button" href="#assets">查看已有拍摄样品档案 →</a></section>`;}
 async function creation(signal,user){
  const [materials,templates,tasks]=await Promise.all([api.materials(signal),api.templates(signal),api.workTasks(signal)]);if(signal.aborted)return;
  let rows=[],broken=false,current=null,dirty=false,saveTimer;
  try{rows=readDrafts(localStorage,user.id);}catch{broken=true;}
  $('#main').innerHTML=heading('内容创作','带着参考开始写，先把想法整理成可执行的内容。')+`<div class="creation-notice">草稿仅保存在本机浏览器，按当前登录用户隔离；尚未同步团队，也不会自动发布。</div><section class="creation-workspace"><aside class="draft-sidebar"><button class="primary" id="new-draft">＋ 新建草稿</button><div id="draft-list"></div></aside><form id="draft-form" class="draft-editor"><div class="form-grid"><label>草稿名称<input name="name" maxlength="100" placeholder="给这份内容起个名字"></label><label>关联执行事项<select name="taskId"><option value="">暂不关联</option>${tasks.map(t=>`<option value="${h(t.id)}">${h(t.title)}</option>`).join('')}</select></label></div><div class="form-grid"><label>参考素材<select name="materialId"><option value="">暂不选择</option>${materials.map(m=>`<option value="${h(m.id)}">${h(m.title)}</option>`).join('')}</select></label><label>使用模板<select name="templateId"><option value="">暂不选择</option>${templates.filter(t=>!t.archived).map(t=>`<option value="${h(t.id)}">${h(t.name)}</option>`).join('')}</select></label></div><div class="draft-reference" id="draft-reference"></div><label>内容标题<input name="title" maxlength="200" placeholder="想让读者看到的第一句话"></label><label>正文<textarea name="body" rows="12" maxlength="20000" placeholder="写下正文、产品表达与行动引导。"></textarea></label><label>封面说明<textarea name="coverNote" rows="3" maxlength="3000" placeholder="画面、文字重点、需要准备的素材。"></textarea></label><div class="draft-actions"><button class="primary" type="submit" id="save-draft">保存本机草稿</button><button class="secondary" type="button" id="copy-draft">复制标题与正文</button><button class="secondary" type="button" id="export-draft">导出 Markdown</button></div><p id="draft-save-state" class="muted"></p></form></section>`;
  const form=$('#draft-form');
  function collect(){return {id:current||crypto.randomUUID(),name:form.elements.name.value.trim()||'未命名草稿',title:form.elements.title.value.trim(),body:form.elements.body.value,coverNote:form.elements.coverNote.value,materialId:form.elements.materialId.value,templateId:form.elements.templateId.value,taskId:form.elements.taskId.value,updatedAt:new Date().toISOString()};}
  const reference=()=>{const m=materials.find(m=>m.id===form.elements.materialId.value),t=templates.find(t=>t.id===form.elements.templateId.value);$('#draft-reference').innerHTML=(m?`<button type="button" class="text-button" data-live-material="${h(m.id)}">查看参考素材 →</button>`:'')+(t?`<span class="muted">模板：${h(t.name)}</span><button type="button" class="text-button" id="insert-structure">插入模板结构</button>`:'')+(form.elements.taskId.value?`<button type="button" class="text-button" data-live-task="${h(form.elements.taskId.value)}">查看关联事项 →</button>`:'');const insert=$('#insert-structure');if(insert)insert.onclick=()=>{const value=t.structure||'';form.elements.body.value+=(form.elements.body.value?'\n\n':'')+value;dirty=true;persist(true);$('#draft-save-state').textContent='模板结构已插入并保存本机草稿，未增加后台使用次数。';};};
  function list(){ $('#draft-list').innerHTML=rows.map(d=>`<button class="draft-item ${d.id===current?'active':''}" type="button" data-draft-id="${h(d.id)}"><b>${h(d.name)}</b><small>${h(d.updatedAt.slice(0,16).replace('T',' '))}</small></button>`).join('')||'<p class="muted">还没有本机草稿。</p>'; }
  function persist(silent=false){if(broken)return false;clearTimeout(saveTimer);const d=collect();try{rows=saveDraft(localStorage,user.id,d);current=d.id;dirty=false;list();$('#draft-save-state').textContent='已自动保存在本机，尚未同步云端。';if(!silent)notify('本机草稿已保存');return true;}catch{$('#draft-save-state').textContent='本机保存失败，请先导出当前草稿。';if(!silent)notify('草稿未保存，请先导出备份');return false;}}
  function open(id=null){if(dirty&&!persist(true)){notify('保存失败，请先导出当前草稿再切换');return;}const d=rows.find(d=>d.id===id);current=d?.id||null;form.reset();if(d)for(const key of ['name','title','body','coverNote','materialId','templateId','taskId']){const field=form.elements[key];if(field.tagName==='SELECT'&&d[key]&&![...field.options].some(o=>o.value===d[key]))field.add(new Option('原关联暂不可用',d[key]));field.value=d[key];}dirty=false;reference();list();$('#draft-save-state').textContent=d?'已加载本机草稿。':'新草稿尚未保存。';}
  form.oninput=()=>{dirty=true;$('#draft-save-state').textContent='正在保存本机草稿…';clearTimeout(saveTimer);saveTimer=setTimeout(()=>{if(!signal.aborted)persist(true);},450);};form.elements.materialId.onchange=reference;form.elements.templateId.onchange=reference;form.elements.taskId.onchange=reference;
  form.onsubmit=e=>{e.preventDefault();if(broken){notify('已有草稿格式异常，原数据未覆盖');return;}persist();};
  const flush=()=>{clearTimeout(saveTimer);if(dirty&&!broken)persist(true);};window.addEventListener('pagehide',flush);
  signal.addEventListener('abort',()=>{flush();window.removeEventListener('pagehide',flush);},{once:true});
  $('#new-draft').onclick=()=>open();$('#draft-list').onclick=e=>{const b=e.target.closest('[data-draft-id]');if(b)open(b.dataset.draftId);};
  $('#copy-draft').onclick=async()=>{const d=collect();try{await navigator.clipboard.writeText(d.title+'\n\n'+d.body);notify('已复制标题与正文');}catch{notify('复制未完成，可以选中文字复制');}};
  $('#export-draft').onclick=()=>{const d=collect(),url=URL.createObjectURL(new Blob([draftMarkdown(d)],{type:'text/markdown;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=(d.name.replace(/[\\/:*?"<>|]/g,'_')||'content-draft')+'.md';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
  if(broken){$('#save-draft').disabled=true;$('#draft-save-state').textContent='已有草稿读取异常，原数据保留。可导出当前编辑内容。';}else open(rows[0]?.id);
 }
 return {async render(page,signal,user){if(page==='account-info')accountIndex();if(page==='warehouse')await inventory(signal);if(page==='creation')await creation(signal,user);}};
}
